css:
.trustdial-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf3;
    background: radial-gradient(1200px 500px at 80% -10%, #173243 0%, #0e1c27 45%, #0a141d 100%);
    border-radius: 18px;
}

.trustdial-container * {
    box-sizing: border-box;
}

.trustdial-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0d2a3a 0%, #11465a 55%, #15807a 100%);
    color: #f0fbfa;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(4, 16, 24, 0.55);
    border: 1px solid rgba(45, 212, 191, 0.18);
}

.trustdial-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.trustdial-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 210, 122, 0.12);
    border: 1px solid rgba(255, 210, 122, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.trustdial-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c3e6e2;
}

.trustdial-context {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.trustdial-ctx {
    flex: 1;
    background: #11202c;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(4, 16, 24, 0.4);
    border: 1px solid rgba(120, 150, 168, 0.14);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.trustdial-ctx-contract { border-left: 5px solid #f0a24b; }
.trustdial-ctx-team { border-left: 5px solid #2dd4bf; }

.trustdial-ctx-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #e7edf3;
}

.trustdial-ctx-contract .trustdial-ctx-name { color: #f0a24b; }
.trustdial-ctx-team .trustdial-ctx-name { color: #2dd4bf; }

.trustdial-ctx-meta {
    font-size: 0.82rem;
    color: #9fb2bf;
    line-height: 1.45;
}

.trustdial-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebecb;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.trustdial-period-counter #currentDay,
.trustdial-period-counter #maxPeriods {
    font-weight: 800;
    color: #2dd4bf;
}

.trustdial-round-name {
    background: rgba(45, 212, 191, 0.16);
    color: #5ee6d2;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.trustdial-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f0a24b;
    background: rgba(240, 162, 75, 0.14);
    border: 1px solid rgba(240, 162, 75, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.trustdial-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.trustdial-status-card {
    background: #11202c;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(4, 16, 24, 0.42);
    border-top: 4px solid #2dd4bf;
    border-right: 1px solid rgba(120, 150, 168, 0.12);
    border-bottom: 1px solid rgba(120, 150, 168, 0.12);
    border-left: 1px solid rgba(120, 150, 168, 0.12);
}

.trustdial-card-motivation { border-top-color: #2dd4bf; }
.trustdial-card-velocity { border-top-color: #5b9bd5; }
.trustdial-card-flight { border-top-color: #f0a24b; }
.trustdial-card-delivery { border-top-color: #a98bdd; }

.trustdial-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ba0ad;
}

.trustdial-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #e7edf3;
    font-variant-numeric: tabular-nums;
}

.trustdial-card-motivation .trustdial-value { color: #2dd4bf; }
.trustdial-card-velocity .trustdial-value { color: #7bb6ec; }
.trustdial-card-flight .trustdial-value { color: #f0a24b; }
.trustdial-card-delivery .trustdial-value { color: #b89cea; }

.trustdial-sublabel {
    font-size: 0.74rem;
    color: #8295a3;
    line-height: 1.35;
}

/* Danger / good states for the flight-risk card */
.trustdial-card-flight.trustdial-flight-danger { border-top-color: #ef5350; }
.trustdial-card-flight.trustdial-flight-danger .trustdial-value { color: #ef5350; }
.trustdial-card-flight.trustdial-flight-good { border-top-color: #2dd4bf; }
.trustdial-card-flight.trustdial-flight-good .trustdial-value { color: #2dd4bf; }

/* Delivery card emphasis */
.trustdial-card-delivery.trustdial-delivery-danger .trustdial-value { color: #ef5350; }
.trustdial-card-delivery.trustdial-delivery-good .trustdial-value { color: #2dd4bf; }

.trustdial-trust-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11202c;
    border: 1px solid rgba(120, 150, 168, 0.16);
    color: #aebecb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.trustdial-trust-bar #trustDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #ef5350;
    font-weight: 800;
}

.trustdial-trust-bar.trustdial-trust-good #trustDisplay { color: #2dd4bf; }
.trustdial-trust-bar.trustdial-trust-mid #trustDisplay { color: #f0a24b; }

.trustdial-briefing {
    display: flex;
    gap: 14px;
    background: #11202c;
    border-left: 5px solid #2dd4bf;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(4, 16, 24, 0.4);
    border-top: 1px solid rgba(120, 150, 168, 0.12);
    border-right: 1px solid rgba(120, 150, 168, 0.12);
    border-bottom: 1px solid rgba(120, 150, 168, 0.12);
}

.trustdial-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.trustdial-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #e7edf3;
    margin-bottom: 6px;
}

.trustdial-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #bccbd6;
}

.trustdial-briefing-text strong { color: #5ee6d2; }
.trustdial-briefing-text em { color: #f0a24b; font-style: italic; }

.trustdial-controls {
    background: #11202c;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(4, 16, 24, 0.4);
    border: 1px solid rgba(120, 150, 168, 0.12);
}

.trustdial-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e7edf3;
    border-bottom: 2px solid rgba(120, 150, 168, 0.18);
    padding-bottom: 8px;
}

.trustdial-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cddae3;
    margin: 14px 0 6px;
}

.trustdial-container select,
.trustdial-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c4252;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1924;
    color: #e7edf3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.trustdial-container select:focus,
.trustdial-container input[type="number"]:focus {
    outline: none;
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.22);
}

.trustdial-container select option {
    background-color: #0c1924;
    color: #e7edf3;
}

.trustdial-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2dd4bf;
}

.trustdial-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebecb;
    margin-top: 4px;
}

.trustdial-range-readout span:nth-child(2) {
    color: #2dd4bf;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.trustdial-hint {
    font-size: 0.8rem;
    color: #8295a3;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}

.trustdial-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.trustdial-container .btn-primary {
    background: linear-gradient(135deg, #11808a 0%, #2dd4bf 100%);
    border: none;
    color: #052029;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(45, 212, 191, 0.28);
}

.trustdial-container .btn-primary:hover {
    filter: brightness(1.08);
}

.trustdial-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2c4252;
    color: #aebecb;
    background: transparent;
}

.trustdial-coach {
    background: linear-gradient(160deg, #0d2435 0%, #102f3f 100%);
    color: #d6eceb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 16, 24, 0.45);
    border: 1px solid rgba(45, 212, 191, 0.18);
}

.trustdial-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd27a;
    margin-bottom: 8px;
}

.trustdial-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.trustdial-coach-body strong { color: #5ee6d2; }
.trustdial-coach-body em { color: #ffd27a; font-style: italic; }

.trustdial-history,
.trustdial-chart {
    background: #11202c;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(4, 16, 24, 0.4);
    border: 1px solid rgba(120, 150, 168, 0.12);
}

.trustdial-history h3,
.trustdial-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e7edf3;
}

.trustdial-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #bccbd6;
}

.trustdial-container table#usfHistoryTable th {
    background: #0e1c27;
    color: #5ee6d2;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(45, 212, 191, 0.22);
}

.trustdial-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 150, 168, 0.12);
    color: #bccbd6;
}

.trustdial-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(14, 28, 39, 0.5);
}

.trustdial-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .trustdial-container {
        padding: 14px;
    }
    .trustdial-header h1 {
        font-size: 1.7rem;
    }
    .trustdial-context {
        flex-direction: column;
    }
    .trustdial-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .trustdial-value {
        font-size: 2rem;
    }
    .trustdial-clock {
        margin-left: 0;
    }
    .trustdial-period-counter {
        font-size: 0.88rem;
    }
    .trustdial-trust-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .trustdial-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (trd- prefix; Fjordkart slate-blue theme) ---- */
.trd-completion { padding: 8px 4px 4px; }
.trd-cm-head { text-align: center; margin-bottom: 16px; }
.trd-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f9c; }
.trd-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8295a3; }
.trd-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #17303f; }
.trd-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.trd-cm-yes { background: rgba(47,111,156,0.15); color: #2f6f9c; border: 1px solid rgba(47,111,156,0.45); }
.trd-cm-mid { background: rgba(130,149,163,0.15); color: #5f7286; border: 1px solid rgba(130,149,163,0.42); }
.trd-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.trd-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.trd-cm-metric { flex: 1 1 100px; min-width: 92px; background: rgba(47,111,156,0.07); border: 1px solid rgba(47,111,156,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.trd-cm-mv { display: block; font-size: 1.2rem; font-weight: 800; color: #2f6f9c; }
.trd-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #8295a3; text-transform: uppercase; letter-spacing: 0.03em; }
.trd-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #17303f; }
.trd-cm-insights { margin: 0; padding-left: 20px; }
.trd-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #38484f; }

