(function() {
    'use strict';

    class TrustDialAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Trust Dial`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Fjordkart AS / Nordfrakt build).
            this.START_MOTIVATION = 71;     // index after monitoring rumour (was 82)
            this.START_VELOCITY = 100;      // baseline output index (= ~6 400 productive hrs)
            this.START_FLIGHT = 28;         // key-engineer flight risk (%)
            this.START_TRUST = 6.4;         // team trust score (/10)
            this.HOURS_GAP = 800;           // 7 200 needed − 6 400 available ≈ 12% gap
            this.CONTINGENT_COST = 660;     // NOK 660k if the full 60k/head bonus is paid
            this.TEAM_BONUS_COST = 275;     // ~25k/head across 11 engineers (NOK k)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    motivation: this.START_MOTIVATION,   // intrinsic-motivation index /100
                    velocity: this.START_VELOCITY,       // effective velocity index (100 = baseline)
                    flight: this.START_FLIGHT,           // key-engineer flight risk (%)
                    trust: this.START_TRUST,             // team trust score /10
                    delivery: 52,                        // derived delivery probability (%)
                    gapClosed: 0,                        // hours of the 800-hour gap addressed
                    spend: 0,                            // NOK k committed to pay/recognition
                    // Sticky run-defining penalty flags.
                    surveillanceFlag: false,             // cranked monitoring / coercive control
                    crowdingFlag: false,                 // adopted full performance-contingent bonus
                    gapDenialFlag: false,                // never confronted the real hours gap
                    abdicationFlag: false,               // full autonomy with no shared goal = abdication
                    concentrationFlag: false,            // ignored the two key engineers
                    coercionFlag: false,                 // responded to the setback with coercion
                    keyEngineerLost: false,              // a routing expert walked
                    motivationHistory: [this.START_MOTIVATION],
                    velocityHistory: [this.START_VELOCITY],
                    flightHistory: [this.START_FLIGHT],
                    trustHistory: [this.START_TRUST],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the board's instinct and the
                // classic errors — a blind click-through must NOT auto-win.
                state.decisions = {
                    threat: `none`,
                    gap: `pressure`,
                    posture: `tighten`,
                    scheme: `contingent`,
                    framing: `control`,
                    capacity: 0,
                    monitoring: 8,
                    autonomy: 3,
                    goal: 3,
                    protect: `ignore`,
                    setback: `coerce`,
                    renegotiate: `hold`,
                    board: `reassure`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`threatInput`);
                const ga = document.getElementById(`gapInput`);
                const po = document.getElementById(`postureInput`);
                if (th) decisions.threat = th.value;
                if (ga) decisions.gap = ga.value;
                if (po) decisions.posture = po.value;
                if (!decisions.threat || !decisions.gap || !decisions.posture) { warn(`warn_select`); return false; }
            } else if (round === 2) {
                const sc = document.getElementById(`schemeInput`);
                const fr = document.getElementById(`framingInput`);
                const ca = document.getElementById(`capacityInput`);
                if (sc) decisions.scheme = sc.value;
                if (fr) decisions.framing = fr.value;
                if (ca) decisions.capacity = parseInt(ca.value, 10);
                if (!Number.isFinite(decisions.capacity) || decisions.capacity < 0 || decisions.capacity > 800) {
                    warn(`warn_capacity_range`); return false;
                }
            } else if (round === 3) {
                const mo = document.getElementById(`monitoringInput`);
                const au = document.getElementById(`autonomyInput`);
                const go = document.getElementById(`goalInput`);
                const pr = document.getElementById(`protectInput`);
                if (mo) decisions.monitoring = parseInt(mo.value, 10);
                if (au) decisions.autonomy = parseInt(au.value, 10);
                if (go) decisions.goal = parseInt(go.value, 10);
                if (pr) decisions.protect = pr.value;
                if (!Number.isFinite(decisions.monitoring) || decisions.monitoring < 0 || decisions.monitoring > 10) { warn(`warn_dial_range`); return false; }
                if (!Number.isFinite(decisions.autonomy) || decisions.autonomy < 0 || decisions.autonomy > 10) { warn(`warn_dial_range`); return false; }
                if (!Number.isFinite(decisions.goal) || decisions.goal < 0 || decisions.goal > 10) { warn(`warn_dial_range`); return false; }
            } else if (round === 4) {
                const se = document.getElementById(`setbackInput`);
                const re = document.getElementById(`renegotiateInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (se) decisions.setback = se.value;
                if (re) decisions.renegotiate = re.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let motDelta = 0, velDelta = 0, flightDelta = 0, trustDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: name where the threat sits, read the gap honestly, set posture.
                switch (d.threat) {
                    case `surveillance`: trustDelta += 0.4; motDelta += 2; coachKey = `coach_r1_surveillance`; break;
                    case `logging`: trustDelta += 0.1; coachKey = `coach_r1_logging`; break;
                    case `none`: motDelta -= 2; trustDelta -= 0.3; coachKey = `coach_r1_none`; break;
                }

                switch (d.gap) {
                    case `real`: trustDelta += 0.3; coachKey = `coach_r1_gapreal`; break;
                    case `pressure`: ds.gapDenialFlag = true; coachKey = `coach_r1_gappressure`; break;
                    case `denial`: ds.gapDenialFlag = true; motDelta -= 2; coachKey = `coach_r1_gapdenial`; break;
                }

                switch (d.posture) {
                    case `outcome`: motDelta += 4; trustDelta += 0.7; flightDelta -= 4; if (d.threat === `surveillance` && d.gap === `real`) coachKey = `coach_r1_sharp`; break;
                    case `tighten`: motDelta -= 6; trustDelta -= 0.9; flightDelta += 7; ds.surveillanceFlag = true; coachKey = `coach_r1_tighten`; break;
                    case `refuse`: trustDelta += 0.2; flightDelta -= 1; coachKey = `coach_r1_refuse`; break;
                }

                summaryKey = (d.threat === `surveillance` && d.gap === `real` && d.posture === `outcome`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the pay & recognition scheme (crowding-out is the headline trap here).
                switch (d.scheme) {
                    case `contingent`:
                        ds.crowdingFlag = true;            // sticky: full performance-contingent bonus crowds out intrinsic drive
                        ds.spend += this.CONTINGENT_COST;
                        motDelta -= 7; trustDelta -= 0.8; flightDelta += 6; velDelta += 2;
                        coachKey = `coach_r2_contingent`;
                        break;
                    case `teambonus`:
                        ds.spend += this.TEAM_BONUS_COST;
                        motDelta += 2; trustDelta += 0.3;
                        coachKey = `coach_r2_teambonus`;
                        break;
                    case `recognition`:
                        ds.spend += 220;
                        motDelta += 6; trustDelta += 0.6; flightDelta -= 3;
                        coachKey = `coach_r2_recognition`;
                        break;
                    case `reinvest`:
                        ds.spend += this.CONTINGENT_COST;
                        velDelta += 6; motDelta += 1;
                        ds.gapClosed = Math.min(this.HOURS_GAP, ds.gapClosed + 300); // a third squad closes part of the gap
                        coachKey = `coach_r2_reinvest`;
                        break;
                }

                // Framing changes the MEANING of the same money (informational vs controlling).
                switch (d.framing) {
                    case `trust`:
                        motDelta += 4; trustDelta += 0.6;
                        if (d.scheme === `contingent`) { ds.crowdingFlag = false; motDelta += 2; coachKey = `coach_r2_reframe`; } // reframed upside-share softens the crowding-out
                        break;
                    case `control`:
                        motDelta -= 3; trustDelta -= 0.5; flightDelta += 2;
                        if (d.scheme === `contingent`) ds.crowdingFlag = true;
                        break;
                    case `silent`:
                        trustDelta -= 0.2;
                        break;
                }

                // Acting on the real hours gap (capacity / scope cut) is the only thing that buys hours.
                ds.gapClosed = Math.min(this.HOURS_GAP, ds.gapClosed + d.capacity);
                if (d.capacity >= 600) { velDelta += 5; ds.gapDenialFlag = false; }
                else if (d.capacity >= 300) { velDelta += 2; ds.gapDenialFlag = false; }
                else if (d.capacity === 0 && d.scheme !== `reinvest`) { ds.gapDenialFlag = true; }

                summaryKey = (d.scheme === `contingent` && d.framing !== `trust`) ? `sum_r2_crowding` :
                             ((d.scheme === `recognition` || d.scheme === `reinvest` || (d.scheme === `contingent` && d.framing === `trust`)) && d.capacity >= 300) ? `sum_r2_good` :
                             `sum_r2_weak`;
            } else if (round === 3) {
                // The core round: the three dials on the inverted-U + protecting the two key engineers.
                const mon = d.monitoring, aut = d.autonomy, goal = d.goal;

                // Monitoring: low (outcome-based) is healthy; high (surveillance) crushes motivation & velocity.
                if (mon >= 8) {
                    ds.surveillanceFlag = true;       // sticky: real-time activity surveillance
                    motDelta -= 10; velDelta -= 9; trustDelta -= 1.3; flightDelta += 9;
                    coachKey = `coach_r3_surveillance`;
                } else if (mon >= 5) {
                    motDelta -= 3; velDelta -= 2; trustDelta -= 0.4; flightDelta += 2;
                } else {
                    motDelta += 3; trustDelta += 0.5;
                }

                // Autonomy & goal structure together form the inverted-U.
                // Best is MODERATE-HIGH autonomy with a co-owned goal (enabling structure).
                if (aut >= 8 && goal <= 3) {
                    // Autonomy without shared structure = abdication; the critical path drifts.
                    ds.abdicationFlag = true;          // sticky: trust mistaken for absence of structure
                    velDelta -= 7; trustDelta -= 0.3; motDelta += 1;
                    coachKey = `coach_r3_abdication`;
                } else if (aut <= 2) {
                    // Manager assigns everything = control; motivation and trust fall.
                    motDelta -= 6; trustDelta -= 0.7; flightDelta += 3; velDelta -= 2;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_control`;
                } else {
                    // Moderate-to-high autonomy = the enabling band.
                    motDelta += 5; trustDelta += 0.5; velDelta += 3;
                }

                if (goal >= 6 && goal <= 9) {
                    // Co-owned commitment with transparency on the constraint.
                    motDelta += 4; velDelta += 5; trustDelta += 0.6;
                    if (aut >= 5 && aut <= 8 && mon <= 4) coachKey = `coach_r3_enabling`;
                } else if (goal <= 2) {
                    velDelta -= 3; trustDelta -= 0.4;
                } else if (goal === 10) {
                    // Pure "co-own everything" with no anchor still drifts a little.
                    velDelta -= 1;
                }

                // Protecting the two routing experts — concentration risk.
                switch (d.protect) {
                    case `targeted`: flightDelta -= 12; trustDelta += 0.4; ds.concentrationFlag = false; break;
                    case `generic`: flightDelta -= 3; break;
                    case `ignore`: ds.concentrationFlag = true; flightDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_concentration`; break;
                }

                summaryKey = (mon <= 4 && aut >= 5 && aut <= 8 && goal >= 6 && goal <= 9 && d.protect === `targeted`) ? `sum_r3_good` :
                             (mon >= 8 ? `sum_r3_surveillance` :
                             (aut >= 8 && goal <= 3 ? `sum_r3_abdication` :
                             (aut <= 2 ? `sum_r3_control` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Recover & re-forecast after the week-6 setback.
                switch (d.setback) {
                    case `rebuild`: motDelta += 7; trustDelta += 1.0; flightDelta -= 10; velDelta += 3; coachKey = `coach_r4_rebuild`; break;
                    case `coerce`: ds.coercionFlag = true; ds.surveillanceFlag = true; motDelta -= 9; trustDelta -= 1.2; flightDelta += 12; velDelta -= 6; coachKey = `coach_r4_coerce`; break;
                    case `absorb`: motDelta -= 4; trustDelta -= 0.5; velDelta -= 3; ds.gapDenialFlag = true; coachKey = `coach_r4_absorb`; break;
                }

                switch (d.renegotiate) {
                    case `rescope`: velDelta += 4; trustDelta += 0.5; ds.gapClosed = Math.min(this.HOURS_GAP, ds.gapClosed + 400); ds.gapDenialFlag = false; coachKey = (d.setback === `rebuild`) ? `coach_r4_rescope` : coachKey; break;
                    case `hold`: ds.gapDenialFlag = true; trustDelta -= 0.4; velDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_hold` : coachKey; break;
                    case `penalty`: trustDelta -= 0.2; break;
                }

                switch (d.board) {
                    case `honest`: trustDelta += 0.6; motDelta += 2; if (d.setback === `rebuild` && d.renegotiate === `rescope`) coachKey = `coach_r4_honest`; break;
                    case `reassure`: trustDelta -= 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r4_reassure` : coachKey; break;
                    case `blame`: trustDelta -= 0.9; motDelta -= 3; flightDelta += 3; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { motDelta += 2; trustDelta += 0.3; }
                else if (d.conviction <= 25) { trustDelta -= 0.3; }

                summaryKey = (d.setback === `rebuild` && d.renegotiate === `rescope` && d.board === `honest`) ? `sum_r4_good` :
                             (d.setback === `coerce` ? `sum_r4_coerce` : `sum_r4_weak`);
            }

            // ---- Apply deltas (clamped). ----
            ds.motivation = Math.max(0, Math.min(100, Math.round((ds.motivation + motDelta) * 10) / 10));
            ds.velocity = Math.max(0, Math.min(140, Math.round((ds.velocity + velDelta) * 10) / 10));
            ds.flight = Math.max(0, Math.min(100, Math.round((ds.flight + flightDelta) * 10) / 10));
            ds.trust = Math.max(0, Math.min(10, Math.round((ds.trust + trustDelta) * 10) / 10));

            // ---- Sticky-flag CAPS (run-defining penalties that a later good round cannot wash out). ----
            // Surveillance: motivation cannot recover above 60, velocity capped — control manufactures the failure.
            if (ds.surveillanceFlag) {
                ds.motivation = Math.min(ds.motivation, 59);
                ds.velocity = Math.min(ds.velocity, 96);
            }
            // Crowding-out: the contingent bonus caps motivation and trust for knowledge workers.
            if (ds.crowdingFlag) {
                ds.motivation = Math.min(ds.motivation, 66);
                ds.trust = Math.min(ds.trust, 6.0);
            }
            // Abdication: autonomy without a shared goal drifts off the critical path — velocity capped.
            if (ds.abdicationFlag) {
                ds.velocity = Math.min(ds.velocity, 94);
            }

            // ---- A key engineer walks once flight risk crosses 40% (concentration risk). ----
            if (ds.flight >= 40 && !ds.keyEngineerLost) {
                ds.keyEngineerLost = true;
                ds.velocity = Math.min(ds.velocity, 78);   // 4–5 months of routing velocity lost
            }

            // ---- Delivery probability is DERIVED: velocity, motivation, flight risk, and the closed gap. ----
            const velFactor = ds.velocity / 100;                              // ~0.8..1.4
            const motFactor = 0.6 + 0.4 * (ds.motivation / 100);              // 0.6..1.0
            const flightFactor = 1 - (ds.flight / 100) * 0.6;                 // 1.0..0.4
            const gapFactor = 0.55 + 0.45 * (ds.gapClosed / this.HOURS_GAP);  // 0.55..1.0
            let delivery = 100 * velFactor * motFactor * flightFactor * gapFactor;

            // The gap that no bonus can close: if the hours gap was never confronted, delivery is capped.
            if (ds.gapDenialFlag) delivery = Math.min(delivery, 55);
            // A lost key engineer puts the date out of reach regardless of dashboards.
            if (ds.keyEngineerLost) delivery = Math.min(delivery, 48);
            // Surveillance/coercion makes the deadline LESS likely, not more.
            if (ds.surveillanceFlag) delivery = Math.min(delivery, 60);

            ds.delivery = Math.max(0, Math.min(99, Math.round(delivery)));

            ds.motivationHistory.push(ds.motivation);
            ds.velocityHistory.push(Math.round(ds.velocity));
            ds.flightHistory.push(ds.flight);
            ds.trustHistory.push(ds.trust);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period.
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                motivation: ds.motivation,
                motivationDelta: Math.round(motDelta * 10) / 10,
                velocity: Math.round(ds.velocity),
                flight: ds.flight,
                trust: ds.trust,
                delivery: ds.delivery,
                keyEngineerLost: ds.keyEngineerLost,
                spend: ds.spend,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _trustClass(v) {
            if (v >= 7.5) return `good`;
            if (v >= 5.5) return `mid`;
            return `low`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`motivationDisplay`, `domainState.motivation`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`velocityDisplay`, `domainState.velocity`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`flightDisplay`, `domainState.flight`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.trustdial-card-flight`);
                if (card) {
                    card.classList.toggle(`trustdial-flight-danger`, n >= 40);
                    card.classList.toggle(`trustdial-flight-good`, n < 25);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`deliveryDisplay`, `domainState.delivery`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.trustdial-card-delivery`);
                if (card) {
                    card.classList.toggle(`trustdial-delivery-danger`, n < 55);
                    card.classList.toggle(`trustdial-delivery-good`, n >= 75);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.trustdial-trust-bar`);
                if (bar) {
                    const cls = self._trustClass(n);
                    bar.classList.toggle(`trustdial-trust-good`, cls === `good`);
                    bar.classList.toggle(`trustdial-trust-mid`, cls === `mid`);
                }
                return self._fmtTrust(n);
            });

            // Live slider readouts.
            this._wireReadout(`capacityInput`, `capacityReadout`);
            this._wireReadout(`monitoringInput`, `monitoringReadout`);
            this._wireReadout(`autonomyInput`, `autonomyReadout`);
            this._wireReadout(`goalInput`, `goalReadout`);
        }

        _wireReadout(inputId, readoutId) {
            const inp = document.getElementById(inputId);
            const out = document.getElementById(readoutId);
            if (inp && out) {
                out.textContent = inp.value;
                inp.addEventListener(`input`, function() { out.textContent = inp.value; });
            }
        }

        _fmtTrust(v) {
            // Locale-aware one-decimal score: en "6.4", es "6,4".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                trustDialChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_motivation`, `Intrinsic motivation (/100)`),
                                data: [],
                                borderColor: `#2dd4bf`,
                                backgroundColor: `rgba(45,212,191,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2dd4bf`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_velocity`, `Effective velocity (index)`),
                                data: [],
                                borderColor: `#5b9bd5`,
                                backgroundColor: `rgba(91,155,213,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#5b9bd5`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_trust`, `Team trust (×10)`),
                                data: [],
                                borderColor: `#a98bdd`,
                                backgroundColor: `rgba(169,139,221,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#a98bdd`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_flight`, `Key-engineer flight risk (%)`),
                                data: [],
                                borderColor: `#f0a24b`,
                                backgroundColor: `rgba(240,162,75,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#f0a24b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#aebecb`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 130, position: `left`,
                                ticks: { color: `#8295a3` }, grid: { color: `rgba(120,150,168,0.10)` },
                                title: { display: true, text: L(`chart_axis_scale`, `index / % / ×10`), color: `#8295a3` }
                            },
                            x: {
                                ticks: { color: `#8295a3` }, grid: { color: `rgba(120,150,168,0.06)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#8295a3` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.motivationHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Trust is /10 — scale ×10 to share the axis with the indices and the percentage.
            const trustScaled = ds.trustHistory.map((v) => Math.round(v * 10));
            return {
                trustDialChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.motivationHistory.map((v) => Math.round(v)) },
                        { data: ds.velocityHistory.map((v) => Math.round(v)) },
                        { data: trustScaled },
                        { data: ds.flightHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            const motivation = Math.round(ds.motivation);
            const velocity = Math.round(ds.velocity);
            const flight = Math.round(ds.flight);
            const trust = Math.round(ds.trust * 10) / 10;
            const delivery = Math.round(ds.delivery);
            const flightScore = 100 - flight;
            const trustScore = trust * 10;
            return Math.max(0, Math.min(100, Math.round(motivation * 0.24 + Math.min(velocity, 115) * 0.20 + flightScore * 0.20 + trustScore * 0.16 + delivery * 0.20)));
        }

        _verdictKey(ds, composite) {
            const motivation = Math.round(ds.motivation);
            const flight = Math.round(ds.flight);
            const trust = Math.round(ds.trust * 10) / 10;
            const delivery = Math.round(ds.delivery);
            const motivated = motivation >= 72;
            const talentHeld = flight < 35 && !ds.keyEngineerLost;
            const trusted = trust >= 7;
            const onTrack = delivery >= 70;
            const cleanRun = !ds.surveillanceFlag && !ds.crowdingFlag && !ds.coercionFlag &&
                             !ds.keyEngineerLost && !ds.concentrationFlag && !ds.abdicationFlag;
            if (cleanRun && motivated && trusted && talentHeld && onTrack && composite >= 76) return `verdict_trust`;
            if (ds.surveillanceFlag || ds.coercionFlag) return `verdict_control`;
            if (ds.crowdingFlag) return `verdict_crowding`;
            if (ds.keyEngineerLost || ds.concentrationFlag) return `verdict_concentration`;
            if (ds.abdicationFlag) return `verdict_abdication`;
            if (ds.gapDenialFlag && !onTrack) return `verdict_planning`;
            if (composite >= 58) return `verdict_compromise`;
            return `verdict_failure`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const motivation = Math.round(ds.motivation);
            const velocity = Math.round(ds.velocity);
            const flight = Math.round(ds.flight);
            const trust = Math.round(ds.trust * 10) / 10;
            const delivery = Math.round(ds.delivery);

            // Composite weighted across the four KPIs + delivery probability.
            const composite = this._composite(ds);

            const motivated = motivation >= 72;
            const fastEnough = velocity >= 100;
            const talentHeld = flight < 35 && !ds.keyEngineerLost;
            const trusted = trust >= 7;
            const onTrack = delivery >= 70;

            // Pattern detection — gated by the sticky flags.
            let pattern = `mixed`;
            if (ds.surveillanceFlag || ds.coercionFlag) pattern = `control`;
            else if (ds.crowdingFlag) pattern = `crowding`;
            else if (ds.concentrationFlag || ds.keyEngineerLost) pattern = `concentration`;
            else if (ds.abdicationFlag) pattern = `abdication`;
            else if (ds.gapDenialFlag) pattern = `planning`;
            else if (motivated && trusted && onTrack && talentHeld) pattern = `trust`;

            // Top verdict is GATED: no sticky run-defining error can reach "Trust-Based Delivery".
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (verdictKey === `verdict_trust`) insights.push(window.mySimulation.t(`insight_trust`));
            else if (pattern === `control`) insights.push(window.mySimulation.t(`insight_control`));
            else if (pattern === `crowding`) insights.push(window.mySimulation.t(`insight_crowding`));
            else if (pattern === `concentration`) insights.push(window.mySimulation.t(`insight_concentration`));
            else if (pattern === `abdication`) insights.push(window.mySimulation.t(`insight_abdication`));
            else if (pattern === `planning`) insights.push(window.mySimulation.t(`insight_planning`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.keyEngineerLost) insights.push(window.mySimulation.t(`insight_engineer_lost`));
            if (ds.surveillanceFlag) insights.push(window.mySimulation.t(`insight_surveillance`));
            if (ds.crowdingFlag) insights.push(window.mySimulation.t(`insight_bonus`));
            if (ds.abdicationFlag) insights.push(window.mySimulation.t(`insight_abdication_tail`));
            if (ds.gapDenialFlag) insights.push(window.mySimulation.t(`insight_gap`));
            if (motivated && trusted && !onTrack && !ds.gapDenialFlag) insights.push(window.mySimulation.t(`insight_happy_late`));

            return {
                motivation: motivation,
                velocity: velocity,
                flight: flight,
                trust: trust,
                delivery: delivery,
                motivated: motivated,
                fastEnough: fastEnough,
                talentHeld: talentHeld,
                trusted: trusted,
                onTrack: onTrack,
                keyEngineerLost: ds.keyEngineerLost,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const motivation = Math.round(Number(s.motivation || 0));
            const velocity = Math.round(Number(s.velocity || 0));
            const trust = this._fmtTrust(Number(s.trust || 0));
            const flight = Math.round(Number(s.flight || 0)) + '%';
            const delivery = Math.round(Number(s.delivery || 0)) + '%';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const trustWon = s.verdictKey === 'verdict_trust';
            const badgeCls = trustWon ? 'trd-cm-yes' : (score >= 62 ? 'trd-cm-mid' : 'trd-cm-no');
            const metric = (val, lab) => '<div class="trd-cm-metric"><span class="trd-cm-mv">' + val + '</span><span class="trd-cm-ml">' + lab + '</span></div>';
            const metrics = metric(motivation, T('cm_m_motivation'))
                + metric(velocity, T('cm_m_velocity'))
                + metric(trust, T('cm_m_trust'))
                + metric(flight, T('cm_m_flight'))
                + metric(delivery, T('cm_m_delivery'));
            return ''
                + '<div class="trd-completion">'
                +   '<div class="trd-cm-head">'
                +     '<div class="trd-cm-score">' + score + '<span class="trd-cm-score-max">/100</span></div>'
                +     '<div class="trd-cm-grade">' + verdict + ' <span class="trd-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="trd-cm-metrics">' + metrics + '</div>'
                +   '<div class="trd-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="trd-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.keyEngineerLost) return window.mySimulation.t(`hint_engineer_lost`);
            if (ds.surveillanceFlag) return window.mySimulation.t(`hint_surveillance`);
            if (ds.flight >= 38) return window.mySimulation.t(`hint_flight`);
            if (ds.crowdingFlag) return window.mySimulation.t(`hint_crowding`);
            if (ds.gapDenialFlag && state.currentPeriod >= 2) return window.mySimulation.t(`hint_gap`);
            if (ds.motivation < 60) return window.mySimulation.t(`hint_motivation`);
            if (ds.motivation >= 72 && ds.trust >= 7 && ds.delivery >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.motivation`, label: `Motivation`, i18nKey: `col_motivation`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.velocity`, label: `Velocity`, i18nKey: `col_velocity`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.flight`, label: `Flight`, i18nKey: `col_flight`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => self._fmtTrust(Number(v)) },
                { key: `results.delivery`, label: `Delivery`, i18nKey: `col_delivery`, formatter: (v) => `${Math.round(v)}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

